    ["Dagannoth Mother (Blood Runs Deep)"] = {
        ["Argh! That axe! Where did you get it?"] = "¡Argh! ¡Ese hacha! ¿Dónde lo conseguiste?",
    },
    ["Dagannoth Mother"] = {
        ["Argh! That axe! Where did you get it?"] = "¡Argh! ¡Ese hacha! ¿Dónde lo conseguiste?",
    },
    ["Dagon the Gatekeeper"] = {
        ["You lost your Pact with Dagon, who is me. I'll hold on to it until you have room to take it."] = "Perdiste tu pacto con Dagon, que soy yo. Lo guardaré hasta que tengas espacio para llevarlo.",
        ["Here, you lost this... It won't work for anyone else, so take better care of such a valuable thing. Better yet, just sign it now! It's perfectly safe."] = "Toma, perdiste esto... No funcionará para nadie más, así que cuida mejor algo tan valioso. Mejor aún, ¡fírmelo ahora! Es perfectamente seguro.",
        ["Now that you have released me, I am free to pursue my revenge. However, I find myself in need of a new weapon - the blades of my katars have dulled. If you would bring me a pair of newly restored hellfire katars, I have one more gift for you. My rage has built up such that I am no longer in need of it."] = "Ahora que me has liberado, soy libre de perseguir mi venganza. Sin embargo, necesito una nueva arma: las hojas de mis katars se han desafilado. Si me traes un par de katars Hellfire recién restaurados, tengo un regalo más para ti. Mi ira ha aumentado de tal manera que ya no la necesito.",
        ["I'll see if I can scare up a pair of hellfire katars for you."] = "Veré si puedo conseguirte un par de katares de fuego infernal.",
        ["Ooh, I have one of those!"] = "¡Oh, tengo uno de esos!",
        ["I am in need of two."] = "Necesito dos.",
        ["I have a pair of hellfire katars right here, as it goes..."] = "Tengo un par de katars de fuego infernal justo aquí, tal como dice...",
        ["Give two hellfire katars to Dagon?"] = "¿Darle dos katars de fuego infernal a Dagon?",
        ["Yes."] = "Sí.",
        ["Be warned: Razulei was known for crafting items of power, but also items that inflicted pain on their user."] = "Tenga cuidado: Razulei era conocido por crear objetos de poder, pero también objetos que infligían dolor a su usuario.",
        ["Wait, are these knuckle dusters cursed?"] = "Espera, ¿están malditos estos nudillos?",
        ["Not cursed. Their effect is more subtle than that, and perhaps more insidious. Rage is addictive, and can become a crutch. Just be careful when using them to not lose yourself."] = "No maldito. Su efecto es más sutil que eso y quizás más insidioso. La ira es adictiva y puede convertirse en una muleta. Sólo ten cuidado al usarlos para no perderte.",
        ["You are not at all how I expected you to be when we first met."] = "No eres en absoluto como esperaba que fueras cuando nos conocimos.",
        ["Why are you still here, Dagon?"] = "¿Por qué sigues aquí, Dagon?",
        ["I am preparing."] = "Me estoy preparando.",
        ["Yeah. It's interesting to me that 'preparing' looks a great bit like sitting on your as-"] = "Sí. Es interesante para mí que \"preparar\" se parece mucho a sentarse sobre el trasero.",
        ["Dare not finish that thought. I shall leave when I am ready to do so, and not a moment before."] = "No te atrevas a terminar ese pensamiento. Me marcharé cuando esté dispuesto a hacerlo, y ni un momento antes.",
    },
    ["Dairy cow"] = {
        ["[You'll need an empty bucket to collect the milk.]"] = "[Necesitarás un balde vacío para recoger la leche.]",
        ["You milk the cow."] = "Tu ordeñas la vaca.",
        ["[You need to have started the Cold War quest to attempt this.]"] = "[Debes haber iniciado la misión Cold War para intentar esto.]",
        ["What are yooo interrupting me for? Can't you see I'm working here?"] = "¿Por qué me interrumpes? ¿No ves que estoy trabajando aquí?",
        ["You need to have started the Cold War quest to attempt this."] = "Debes haber iniciado la misión Cold War para intentar esto.",
        ["Moo, what do yoooou think you're doing?"] = "Moo, ¿qué crees que estás haciendo?",
        ["Err... Nothing. Just checking that your cowbell was working. Don't want you to get lost!"] = "Err... Nada. Sólo comprobaba que tu cencerro funcionaba. ¡No quiero que te pierdas!",
        ["How exactly am I going to get lost when I'm tied down? What were yooo really doing?"] = "¿Cómo exactamente me voy a perder cuando esté atado? ¿Qué estabas haciendo realmente?",
        ["I don't think you'll believe me."] = "No creo que me creas.",
        ["I'm a talking cow, I'll believe almost anything."] = "Soy una vaca que habla, creeré casi cualquier cosa.",
        ["Fine. I need the bell to trick some penguins into helping me get into their secret lair."] = "Bien. Necesito la campana para engañar a unos pingüinos y que me ayuden a entrar en su guarida secreta.",
        ["Well why didn't you say so? I've got a ton of these things. Go ahead and take the bell."] = "Bueno, ¿por qué no lo dijiste? Tengo un montón de estas cosas. Adelante, toca el timbre.",
    },
    ["Dakh'thoulan Aegis"] = {
        ["Hi there."] = "Hola.",
        ["Hello, young one. What brings you to our humble dwelling?"] = "Hola, joven. ¿Qué te trae a nuestra humilde morada?",
        ["I was wondering what this place was?"] = "Me preguntaba qué era este lugar.",
        ["These are the Tunnels of Chaos. They radiate with the energy of chaos magic. At the far end of the tunnel, you will find a portal to the Chaos Altar itself where chaos runes are crafted!"] = "Estos son los Túneles del Caos. Irradian con la energía de la magia del caos. ¡Al final del túnel, encontrarás un portal al Altar del Caos donde se crean las runas del caos!",
        ["Select an option"] = "Seleccione una opción",
        ["Why is the tunnel so short?"] = "¿Por qué el túnel es tan corto?",
        ["The nature of chaos magic itself is mysterious and hard to understand."] = "La naturaleza de la magia del caos en sí es misteriosa y difícil de entender.",
        ["What do you mean?"] = "¿Qué quieres decir?",
        ["The tunnel is here, and yet it is not here. We also are here, where we should be, yet we are somewhere else. And so, the tunnel goes from one place to another, yet touches neither."] = "El túnel está aquí y, sin embargo, no está aquí. Nosotros también estamos aquí, donde deberíamos estar, pero estamos en otro lugar. Y así, el túnel va de un lugar a otro, pero no toca a ninguno de los dos.",
        ["I really don't understand."] = "Realmente no entiendo.",
        ["I told you you wouldn't. The best way to think of it is that the tunnel is like a gateway that allows you to travel from one place in the world to another in a more safe and convenient way."] = "Te dije que no lo harías. La mejor forma de verlo es que el túnel es como una puerta de entrada que permite viajar de un lugar del mundo a otro de una forma más segura y cómoda.",
        ["Oh, I think I see. So it is like a magical alternate route?"] = "Oh, creo que ya veo. ¿Es entonces como una ruta alternativa mágica?",
        ["Exactly! Well done! And at the end, there is a portal which will transport you to the Chaos Altar."] = "¡Exactamente! ¡Bien hecho! Y al final, hay un portal que te transportará al Altar del Caos.",
        ["Oh, ok."] = "Oh, está bien.",
        ["Why are there only three of you?"] = "¿Por qué solo sois tres?",
        ["Is the Wilderness above us?"] = "¿Está el Wilderness por encima de nosotros?",
        ["You seem quite nice for a Zamorakian."] = "Pareces bastante agradable para ser un zamorakiano.",
        ["History is written by the strong and the influential."] = "La historia la escriben los fuertes y los influyentes.",
        ["What does that mean?"] = "¿Qué significa eso?",
        ["It means we cannot always believe what we are told to believe. You would do well to remember that."] = "Significa que no siempre podemos creer lo que nos dicen que creamos. Harías bien en recordarlo.",
        ["I will! Thank you!"] = "¡Lo haré! ¡Gracias!",
        ["Thanks for your time."] = "Gracias por tu tiempo.",
        ["Our order is a secret one and those of us that remain and survive through the ages choose to hide ourselves away."] = "Nuestra orden es secreta y aquellos de nosotros que permanecemos y sobrevivimos a través de los tiempos elegimos escondernos.",
        ["Where are the rest of you now?"] = "¿Dónde está el resto de ustedes ahora?",
        ["We have built or found many tunnels such as these. This is not the only one. Rest assured, there are many more of us around."] = "Hemos construido o encontrado muchos túneles como estos. Éste no es el único. Tenga la seguridad de que somos muchos más por aquí.",
        ["Yes, I can understand you would expect it to be since the tunnel leads to the Chaos Altar. And yet, the tunnel does not enter the Wilderness, no. Rest assured, you are safe here and should not come to harm."] = "Sí, puedo entender que sea de esperar, ya que el túnel conduce al Altar del Caos. Y sin embargo, el túnel no entra en el Wilderness, no. Tenga la seguridad de que aquí está a salvo y no debería sufrir ningún daño.",
        ["Hello, how can I help you?"] = "Hola, ¿en qué puedo ayudarte?",
        ["Where did he go?"] = "¿A dónde fue?",
        ["Where did who go?"] = "¿Adónde fue quién?",
        ["Surok! I saw him come in this way!"] = "¡Surok! ¡Lo vi venir de esta manera!",
        ["Oh, Lord Magis? Why yes; he went through the portal here."] = "¿Oh, Señor Magis? Por qué sí; Pasó por el portal aquí.",
        ["Right! Thanks!"] = "¡Correcto! ¡Gracias!",
        ["Was there anything else?"] = "¿Hubo algo más?",
        ["Yes. What is this place?"] = "Sí. ¿Qué es este lugar?",
        ["Yes, I can understand you expect it to be since the tunnel leads to the Chaos Altar. And yet, the tunnel does not enter the Wilderness, no. Rest assured, you are safe here and should not come to harm."] = "Sí, puedo entender que esperes que así sea, ya que el túnel conduce al Altar del Caos. Y sin embargo, el túnel no entra en el Wilderness, no. Tenga la seguridad de que aquí está a salvo y no debería sufrir ningún daño.",
        ["History is written by the strong and influential."] = "La historia la escriben los fuertes e influyentes.",
    },
    ["Dalal"] = {
        ["Hi!"] = "¡Hola!",
        ["*Dalal may say one of the following at random:*"] = "*Dalal puede decir una de las siguientes palabras al azar:*",
        ["*Dialogue 1:*"] = "*Diálogo 1:*",
        ["A fight over love and money would be a duel purpose."] = "Una pelea por amor y dinero sería un duelo.",
        ["*Dialogue 2:*"] = "*Diálogo 2:*",
        ["What did the skeleton say before it ate?"] = "¿Qué dijo el esqueleto antes de comer?",
        ["I don't know."] = "No lo sé.",
        ["Bone appétit."] = "Apetito de huesos.",
        ["*Dialogue 3:*"] = "*Diálogo 3:*",
        ["My favourite fighter is Mubariz."] = "Mi luchador favorito es Mubariz.",
        ["The guy at the information kiosk?"] = "¿El chico del quiosco de información?",
        ["Yeah! He rocks!"] = "¡Sí! ¡Él es genial!",
        ["Takes all sorts, I guess."] = "Supongo que se aceptan de todo tipo.",
        ["*Dialogue 4:*"] = "*Diálogo 4:*",
        ["Did you know, they think this place dates back to the Second Age."] = "¿Sabías que creen que este lugar se remonta a la Segunda Edad?",
        ["Really?"] = "¿En serio?",
        ["Yeah, the guy at the information kiosk was telling me."] = "Sí, me lo estaba diciendo el chico del quiosco de información.",
        ["*Dialogue 5:*"] = "*Diálogo 5:*",
        ["Why do giants lose all their duels against vampires?"] = "¿Por qué los gigantes pierden todos sus duelos contra vampiros?",
        ["I don't know - why?"] = "No lo sé, ¿por qué?",
        ["The stakes are always too high!"] = "¡Siempre hay mucho en juego!",
        ["*Dialogue 6:*"] = "*Diálogo 6:*",
        ["Ooh, this is exciting."] = "Oh, esto es emocionante.",
        ["Yup!"] = "¡Sí!",
        ["*Dialogue 7:*"] = "*Diálogo 7:*",
        ["Well, this beats doing the shopping."] = "Bueno, esto es mejor que hacer compras.",
        ["*Dialogue 8:*"] = "*Diálogo 8:*",
        ["Can't you see I'm watching the duels?"] = "¿No ves que estoy viendo los duelos?",
